#!/usr/bin/env python3
"""Print the Homebrew formula for actas (Formula/actas.rb).

    python3 .github/scripts/brew_formula.py                 # HEAD-only formula
    python3 .github/scripts/brew_formula.py 2.0.0 <sha256>  # a stable release

The release workflow runs the second form on every stable tag and commits
the result, so `brew install actas` (after tapping this repository) installs
the single-file release asset, checked against its SHA-256.
"""

import re
import sys

REPO = "TsenkoTsenkov/actas"

HEAD = '''# typed: false
# frozen_string_literal: true

# Generated by .github/scripts/brew_formula.py; the release workflow rewrites
# it on every stable tag. Install:
#   brew tap @tap@ https://github.com/@repo@
#   brew install actas
class Actas < Formula
  include Language::Python::Shebang

  desc "Per-project identities (LLM, cloud, GitHub, git, secrets) for terminals and agents"
  homepage "https://github.com/@repo@"
@stable@  license "MIT"
  head "https://github.com/@repo@.git", branch: "main"

  depends_on "python@3.13"
  depends_on "yq" # YAML manifests (actas reads JSON without a YAML parser)

  def install
    script = build.head? ? "bin/actas" : "actas"
    rewrite_shebang detected_python_shebang, script
    bin.install script => "actas"
  end

  test do
    assert_match "actas", shell_output("#{bin}/actas --version")
  end
end
'''

STABLE = '''  url "https://github.com/{repo}/releases/download/v{version}/actas"
  version "{version}"
  sha256 "{sha256}"
'''


def render(stable):
    return HEAD.replace("@tap@", REPO.lower()).replace("@repo@", REPO).replace("@stable@", stable)


def formula(version=None, sha256=None):
    if version is None:
        return render("")
    if not re.fullmatch(r"[0-9]+(\.[0-9]+)*", version):
        raise SystemExit(f"brew_formula: {version!r} is not a stable version (X.Y.Z)")
    if not re.fullmatch(r"[0-9a-f]{64}", sha256 or ""):
        raise SystemExit("brew_formula: the SHA-256 must be 64 lowercase hex digits")
    return render(STABLE.format(repo=REPO, version=version, sha256=sha256))


if __name__ == "__main__":
    if len(sys.argv) not in (1, 3):
        raise SystemExit("usage: brew_formula.py [VERSION SHA256]")
    sys.stdout.write(formula(*sys.argv[1:]))
